components.css:
.ds-button-connect { margin-top: var(--xxs, 8px);
  width: 100%; height: 48px;
  padding: 14px 32px;
  background: var(--rosso, #da291c); color: var(--ink, #ffffff);
  border: none; border-radius: 0;   
  font-family: var(--font, 'Inter', -apple-system, system-ui, sans-serif); font-size: 14px; font-weight: 700;
  letter-spacing: 1.4px; text-transform: uppercase; line-height: 1;
  cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 8px;
  transition: background 0.2s;  }
.ds-button-connect:hover { background: var(--rosso-active, #b01e0a); }
.ds-button-connect:active { background: var(--rosso-active, #b01e0a); }
.ds-button-connect:disabled { opacity: 0.5; cursor: not-allowed; }
.ds-button-connect:focus-visible { outline:2px solid var(--yellow, #fff200); outline-offset:2px; }

.ds-button-send { height: 48px; flex-shrink: 0;
  padding: 14px 32px;
  background: var(--rosso, #da291c); color: var(--ink, #ffffff);
  border: none; border-radius: 0;
  font-family: var(--font, 'Inter', -apple-system, system-ui, sans-serif); font-size: 14px; font-weight: 700;
  letter-spacing: 1.4px; text-transform: uppercase; line-height: 1;
  cursor: pointer; transition: background 0.2s;  }
.ds-button-send:hover { background: var(--rosso-active, #b01e0a); }
.ds-button-send:active { background: var(--rosso-active, #b01e0a); }
.ds-button-send:focus-visible { outline:2px solid var(--yellow, #fff200); outline-offset:2px; }

.ds-button-clear { background: transparent; border: 1px solid var(--hairline, #303030); border-radius: 0;
  color: var(--body, #969696); font-family: var(--font, 'Inter', -apple-system, system-ui, sans-serif); font-size: 11px; font-weight: 600;
  letter-spacing: 1.1px; text-transform: uppercase;
  padding: 6px 12px; cursor: pointer; transition: border-color 0.2s, color 0.2s;  }
.ds-button-clear:hover { border-color: var(--rosso, #da291c); color: var(--rosso, #da291c); }
.ds-button-clear:focus-visible { outline:2px solid var(--yellow, #fff200); outline-offset:2px; }

.ds-button-leave { margin-top: auto;
  background: transparent; border: 1px solid var(--hairline, #303030);
  border-radius: 0; color: var(--body, #969696);
  font-family: var(--font, 'Inter', -apple-system, system-ui, sans-serif); font-size: 12px; font-weight: 600;
  letter-spacing: 0.65px; text-transform: uppercase;
  padding: 10px; cursor: pointer;
  transition: border-color 0.2s, color 0.2s;  }
.ds-button-leave:hover { border-color: var(--rosso, #da291c); color: var(--rosso, #da291c); }
.ds-button-leave:focus-visible { outline:2px solid var(--yellow, #fff200); outline-offset:2px; }

.ds-button-image { width: 48px; height: 48px; flex-shrink: 0;
  background: var(--canvas, #181818); color: var(--body, #969696);
  border: 1px solid var(--hairline, #303030); border-radius: 0;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  transition: border-color 0.2s, color 0.2s;  }
.ds-button-image:hover { border-color: var(--rosso, #da291c); color: var(--rosso, #da291c); }
.ds-button-image:focus-visible { outline:2px solid var(--yellow, #fff200); outline-offset:2px; }

.ds-text-field { background: var(--canvas, #181818);
  border: 1px solid var(--hairline, #303030);
  border-radius: 4px;               
  padding: 14px 16px; height: 48px;
  color: var(--ink, #ffffff); font-family: var(--font, 'Inter', -apple-system, system-ui, sans-serif); font-size: 14px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;  }
.ds-text-field:focus { border-color: var(--rosso, #da291c);
  box-shadow: 0 0 0 2px rgba(218, 41, 28, 0.25); }
.ds-text-field::placeholder { color: var(--muted, #666666); }

.ds-member-tag { font-size: 9px; font-weight: 600; letter-spacing: 1.1px; text-transform: uppercase;
  color: var(--ink, #ffffff); background: var(--rosso, #da291c);
  border-radius: 9999px;            
  padding: 2px 8px; flex-shrink: 0; font-family: var(--font, 'Inter', -apple-system, system-ui, sans-serif); }

.ds-room-info { background: var(--canvas-elev, #303030);
  border: 1px solid var(--hairline, #303030);
  border-radius: 0;                 
  padding: var(--xs, 16px);
  display: flex; flex-direction: column; gap: var(--xxs, 8px); font-family: var(--font, 'Inter', -apple-system, system-ui, sans-serif); }
.ds-room-label {font-size: 11px; font-weight: 600; letter-spacing: 1.1px;
  text-transform: uppercase; color: var(--muted, #666666);}
.ds-room-code {color: var(--rosso, #da291c); font-size: 16px; font-weight: 500;
  word-break: break-all; line-height: 1.4;}
.ds-room-online {display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--body, #969696);}
.ds-online-dot {width: 7px; height: 7px; border-radius: 50%;
  background: var(--rosso, #da291c);
  animation: pulse 2s infinite;}
